<?php
namespace Dth\Crm\Services; use Dth\Crm\Models\{CompanyMatchCandidate,CompanyContact}; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class CompanyMatchReviewService {public function accept(CompanyMatchCandidate $c,?int $actor=null):void{DB::transaction(function()use($c,$actor){if($c->status!=='pending')throw ValidationException::withMessages(['status'=>'Candidate đã được xử lý.']);if($c->contact_id)CompanyContact::updateOrCreate(['company_id'=>$c->suggested_company_id,'contact_id'=>$c->contact_id],['is_primary'=>true,'is_active'=>true]);$c->update(['status'=>'accepted','reviewed_by_user_id'=>$actor,'reviewed_at'=>now()]);});}public function reject(CompanyMatchCandidate $c,?int $actor=null):void{$c->update(['status'=>'rejected','reviewed_by_user_id'=>$actor,'reviewed_at'=>now()]);}}
